2	// SCSS Mixins - Kajaia Bonds Trading Platform
3	// ============================================
4	
5	@use 'variables' as *;
6	
7	// Responsive Breakpoints
8	@mixin sm {
9	  @media (min-width: $breakpoint-sm) { @content; }
10	}
11	
12	@mixin md {
13	  @media (min-width: $breakpoint-md) { @content; }
14	}
15	
16	@mixin lg {
17	  @media (min-width: $breakpoint-lg) { @content; }
18	}
19	
20	@mixin xl {
21	  @media (min-width: $breakpoint-xl) { @content; }
22	}
23	
24	@mixin sm-down {
25	  @media (max-width: #{$breakpoint-sm - 1px}) { @content; }
26	}
27	
28	// Typography
29	@mixin text-title {
30	  font-size: $font-size-xl;
31	  font-weight: $font-weight-semibold;
32	  line-height: $line-height-tight;
33	}
34	
35	@mixin text-heading {
36	  font-size: $font-size-lg;
37	  font-weight: $font-weight-semibold;
38	  line-height: $line-height-tight;
39	}
40	
41	@mixin text-body {
42	  font-size: $font-size-base;
43	  font-weight: $font-weight-regular;
44	  line-height: $line-height-base;
45	}
46	
47	@mixin text-small {
48	  font-size: $font-size-sm;
49	  font-weight: $font-weight-regular;
50	  line-height: $line-height-base;
51	}
52	
53	@mixin text-caption {
54	  font-size: $font-size-xs;
55	  font-weight: $font-weight-medium;
56	  line-height: $line-height-base;
57	}
58	
59	@mixin text-mono {
60	  font-family: $font-family-mono;
61	  font-size: $font-size-xs;
62	}
63	
64	// Layout
65	@mixin container {
66	  max-width: $container-max-width;
67	  margin-inline: auto;
68	  padding-inline: $container-padding;
69	}
70	
71	@mixin flex-center {
72	  display: flex;
73	  align-items: center;
74	  justify-content: center;
75	}
76	
77	@mixin flex-between {
78	  display: flex;
79	  align-items: center;
80	  justify-content: space-between;
81	}
82	
83	// Interactive States
84	@mixin hover-lift {
85	  transition: transform $transition-fast;
86	
87	  &:hover:not(:disabled) {
88	    transform: translateY(-1px);
89	  }
90	}
91	
92	@mixin focus-ring($color) {
93	  &:focus-visible {
94	    outline: 2px solid $color;
95	    outline-offset: 2px;
96	  }
97	}
98	
99	// Card Pattern
100	@mixin card($bg, $border) {
101	  background: $bg;
102	  border: 1px solid $border;
103	  border-radius: $radius-lg;
104	}
105	
106	// Scrollbar Styling
107	@mixin custom-scrollbar($thumb-color, $track-color) {
108	  &::-webkit-scrollbar {
109	    width: 8px;
110	    height: 8px;
111	  }
112	
113	  &::-webkit-scrollbar-track {
114	    background: $track-color;
115	    border-radius: $radius-full;
116	  }
117	
118	  &::-webkit-scrollbar-thumb {
119	    background: $thumb-color;
120	    border-radius: $radius-full;
121	
122	    &:hover {
123	      background: lighten($thumb-color, 10%);
124	    }
125	  }
126	}
127	
128	// Truncate Text
129	@mixin truncate {
