  font-size: $font-size-sm;
  transition: border-color $transition-base;
  min-width: 140px;

  &:focus {
    outline: none;
    border-color: $admin-primary;
  }

  &::placeholder {
    color: $admin-text-muted;
  }
}

select {
  cursor: pointer;
}

