file.content:
@use '../../../../styles/variables' as *;
@use '../../../../styles/mixins' as *;

// Admin theme colors - Light with violet tint
$admin-bg-base: #faf8ff;
$admin-bg-surface: #ffffff;
$admin-bg-elevated: #f3f0ff;
$admin-primary: #8b5cf6;
$admin-secondary: #a855f7;
$admin-accent: #ec4899;
$admin-text-primary: #1e1b4b;
$admin-text-secondary: #4c4878;
$admin-text-muted: #7c7a9c;
$admin-border: #ddd6fe;

:host {
  display: block;
  min-height: 100vh;
  background: linear-gradient(135deg, #f3f0ff 0%, #faf8ff 50%, #fdf4ff 100%);
  @include flex-center;
  padding: $space-6;
}

// ============================================
// Auth Container Block
// ============================================
.auth-container {
  width: 100%;
  max-width: 400px;
  padding: $space-8;
  background: $admin-bg-surface;
  border: 1px solid $admin-border;
  border-radius: $radius-lg;
  box-shadow: 0 10px 40px rgba(139, 92, 246, 0.1), 0 4px 12px rgba(0, 0, 0, 0.05);

  h2 {
    @include text-title;
    text-align: center;
    margin-bottom: $space-6;
    background: linear-gradient(135deg, $admin-primary, $admin-secondary);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
}

// ============================================
// Auth Form Block
// ============================================
.auth-form {
  display: flex;
  flex-direction: column;
  gap: $space-4;

  label {
    display: flex;
    flex-direction: column;
    gap: $space-2;
    font-size: $font-size-sm;
    font-weight: $font-weight-medium;
    color: $admin-text-secondary;
  }

  input {
    padding: $space-3;
    background: $admin-bg-surface;
    border: 1px solid $admin-border;
    border-radius: $radius-sm;
    color: $admin-text-primary;
    font-size: $font-size-sm;
    transition: all $transition-base;

    &::placeholder {
      color: $admin-text-muted;
    }

    &:focus {
      outline: none;
      border-color: $admin-primary;
      box-shadow: 0 0 0 3px rgba($admin-primary, 0.1);
    }
  }

  button[type="submit"] {
    margin-top: $space-2;
    padding: $space-3 $space-4;
    background: linear-gradient(135deg, $admin-primary, $admin-secondary);
    border: none;
    border-radius: $radius-sm;
    color: #ffffff;
    font-size: $font-size-sm;
    font-weight: $font-weight-semibold;
    cursor: pointer;
    transition: all $transition-base;
    @include hover-lift;

    &:hover:not(:disabled) {
      box-shadow: 0 4px 16px rgba($admin-primary, 0.35);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
}

// ============================================
// Messages
// ============================================
.error {
  margin-top: $space-4;
  padding: $space-3;
  background: rgba($error-500, 0.1);
  border-left: 3px solid $error-500;
  border-radius: $radius-sm;
  color: $error-400;
  font-size: $font-size-sm;
}

// ============================================
// Back Link
// ============================================
.back-link {
  display: inline-block;
  margin-top: $space-6;
  color: $admin-primary;
  font-size: $font-size-sm;
  text-decoration: none;
  transition: color $transition-base;

  &:hover {
    color: lighten($admin-primary, 10%);
    text-decoration: underline;
  }
}

