// ============================================
// Shared blue theme - light, flat, marketplace
// (kept under the `user` name so existing @use consumers compile)
// ============================================

@use '../variables' as *;
@use '../mixins' as *;

// Theme Colors (aliases of the shared blue tokens)
$user-primary-400: $blue-600;
$user-primary-500: $blue-600;
$user-primary-600: $blue-700;

$user-secondary-400: $blue-600;
$user-secondary-500: $blue-600;
$user-secondary-600: $blue-700;

$user-accent-400: $ok;
$user-accent-500: $ok;
$user-accent-600: $ok;

$user-bg-base: $page;
$user-bg-surface: $surface;
$user-bg-elevated: $page;
$user-bg-hover: $blue-50;

$user-border-subtle: $line;
$user-border-default: $line;
$user-border-strong: $line-strong;

$user-text-primary: $ink;
$user-text-secondary: $ink-2;
$user-text-muted: $ink-2;

// Flat (no gradients)
$user-gradient-primary: $blue-600;
$user-gradient-accent: $ok;

.user-theme {
  background: $user-bg-base;
  color: $user-text-primary;
  min-height: 100vh;

  @include custom-scrollbar($user-border-strong, $user-bg-surface);
}

// Page Container
.page {
  @include container;
  padding-block: $space-8;

  @media (max-width: #{$breakpoint-md - 1px}) {
    padding-inline: $container-padding-mobile;
    padding-block: $space-6;
  }

  &__header {
    margin-bottom: $space-6;
  }

  &__title {
    @include text-title;
    margin: 0;
  }

  &__subtitle {
    @include text-body;
    color: $user-text-secondary;
    margin-top: $space-2;
  }
}

