// ============================================
.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: $space-6;
  padding: $space-3 $space-5;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-xl;
  box-shadow: $shadow-card;

  @include sm-down {
    flex-direction: column;
    align-items: stretch;
    gap: $space-4;
  }
}

.logo {
  display: inline-flex;
  align-items: center;
  gap: $space-3;

  &-mark {
    width: 36px;
    height: 36px;
