  display: flex;
  align-items: center;
  gap: $space-2;

  @include sm-down {
    justify-content: space-between;
  }
}

.menu-link {
  display: inline-flex;
  align-items: center;
  min-height: $ctl-h;
  padding: 0 $space-3;
  border-radius: $radius-md;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  color: $ink-2;
  transition: background $transition-base, color $transition-base;

  &:hover {
    background: $blue-50;
    color: $blue-700;
  }

  &:focus-visible {
    outline: none;
    box-shadow: $focus-ring;
  }
}

// ============================================
