  backdrop-filter: blur(4px);
  z-index: $z-modal-backdrop;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: $space-4;
  animation: fadeIn 0.2s ease;
}

.dialog {
  width: 100%;
  max-width: 400px;
  background: white;
  border-radius: $radius-xl;
  box-shadow: $shadow-xl;
  padding: $space-6;
  text-align: center;
  animation: scaleIn 0.2s ease;

  &__icon {
    width: 56px;
    height: 56px;
    margin: 0 auto $space-4;
    border-radius: $radius-full;
    display: flex;
    align-items: center;
    justify-content: center;

    svg {
      width: 28px;
      height: 28px;
    }
  }

  &--danger .dialog__icon {
    background: rgba($error-500, 0.1);
    color: $error-500;
  }

  &--warning .dialog__icon {
    background: rgba($warning-500, 0.1);
    color: $warning-500;
  }

  &--info .dialog__icon {
    background: rgba($info-500, 0.1);
    color: $info-500;
  }

  &__title {
    margin: 0 0 $space-2;
    font-size: $font-size-lg;
    font-weight: $font-weight-semibold;
    color: $neutral-900;
  }

  &__message {
    margin: 0 0 $space-6;
    font-size: $font-size-sm;
    color: $neutral-600;
    line-height: $line-height-relaxed;
  }

  &__actions {
    display: flex;
    gap: $space-3;
    justify-content: center;
  }
}

.btn {
  padding: $space-2 $space-5;
  border: none;
  border-radius: $radius-md;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  cursor: pointer;
  transition: all $transition-base;
  min-width: 100px;

  &:focus-visible {
    outline: 2px solid $info-500;
    outline-offset: 2px;
  }

  &--secondary {
    background: $neutral-100;
    color: $neutral-700;

    &:hover {
      background: $neutral-200;
    }

    &:focus-visible {
      outline-color: $neutral-500;
    }
  }

  &--danger {
    background: $error-500;
    color: white;

    &:hover {
      background: $error-600;
    }

    &:focus-visible {
      outline-color: $error-600;
    }
  }

  &--warning {
    background: $warning-500;
    color: white;

    &:hover {
      background: $warning-600;
    }

    &:focus-visible {
      outline-color: $warning-600;
    }
  }

  &--info {
    background: $info-500;
    color: white;

    &:hover {
      background: $info-600;
    }

    &:focus-visible {
      outline-color: $info-600;
    }
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

